#!/usr/bin/env python3
"""
gen_dsc_qp_tables.py - turn Display Core's DSC QP tables
(drivers/gpu/drm/amd/display/dc/dml/dsc/qp_tables.h, MIT, AMD) into an
integer header for hw/dcn32_dsc.c: the kext builds without floating point,
so each row's bpp (a float in steps of 0.5) becomes bpp x 2.

    tools/gen_dsc_qp_tables.py <linux>/.../dml/dsc/qp_tables.h > hw/gen/dsc_qp_tables.h
"""
import re
import sys

src = open(sys.argv[1]).read()
out = [
    "/*",
    " * GENERATED by tools/gen_dsc_qp_tables.py from Linux amdgpu",
    " * drivers/gpu/drm/amd/display/dc/dml/dsc/qp_tables.h (MIT, Copyright",
    " * Advanced Micro Devices): the DSC rate control QP tables, one row per",
    " * target bpp step of 1/2 (bpp_x2 = 2 x the table's float bpp).",
    " * Do not edit; regenerate.",
    " *",
    " * SPDX-License-Identifier: MIT",
    " */",
    "#ifndef RDNA3_DSC_QP_TABLES_H",
    "#define RDNA3_DSC_QP_TABLES_H",
    "",
    "typedef struct rd_dsc_qp_entry {",
    "    unsigned char bpp_x2;",
    "    unsigned char qps[15];",
    "} rd_dsc_qp_entry;",
    "",
]
names = []
for m in re.finditer(r"static const qp_table\s+(qp_table_(\d+)_(\d+)bpc_(max|min))\s*=\s*\{(.*?)\n\};", src, re.S):
    name, body = m.group(1), m.group(5)
    rows = re.findall(r"\{\s*([0-9.]+)\s*,\s*\{([^}]*)\}\s*\}", body)
    out.append(f"static const rd_dsc_qp_entry rd_{name}[] = {{")
    for bpp, qps in rows:
        v = [int(x) for x in qps.split(",")]
        assert len(v) == 15, name
        b2 = float(bpp) * 2
        assert b2 == int(b2), (name, bpp)
        out.append(f"    {{ {int(b2):3d}, {{ {', '.join(f'{x:2d}' for x in v)} }} }},")
    out.append("};")
    out.append("")
    names.append(name)
assert len(names) == 18, names
out.append("#endif")
sys.stdout.write("\n".join(out) + "\n")
